from __future__ import annotations

from cost_models import AccountMetadata, UsageRow


UNKNOWN_BUSINESS_UNIT = "Unknown"


def account_index(accounts: list[AccountMetadata]) -> dict[str, AccountMetadata]:
    return {account.linked_account_id: account for account in accounts}


def active_accounts(accounts: list[AccountMetadata]) -> list[AccountMetadata]:
    return [account for account in accounts if account.account_status == "ACTIVE"]


def account_for_row(row: UsageRow, accounts: list[AccountMetadata]) -> AccountMetadata | None:
    return account_index(accounts).get(row.linked_account_id)


def account_name_for(account_id: str, accounts: list[AccountMetadata]) -> str:
    account = account_index(accounts).get(account_id)
    if account is None:
        return "unknown-account"
    return account.account_name


def business_unit_for(account_id: str, accounts: list[AccountMetadata]) -> str:
    account = account_index(accounts).get(account_id)
    if account is None:
        return UNKNOWN_BUSINESS_UNIT
    return account.business_unit


def activated_tags_for(account_id: str, accounts: list[AccountMetadata]) -> tuple[str, ...]:
    account = account_index(accounts).get(account_id)
    if account is None:
        return ()
    return account.activated_tag_keys


def accounts_by_business_unit(accounts: list[AccountMetadata]) -> dict[str, list[str]]:
    grouped: dict[str, list[str]] = {}
    for account in accounts:
        grouped.setdefault(account.business_unit, []).append(account.linked_account_id)
    for account_ids in grouped.values():
        account_ids.sort()
    return grouped


def owner_email_for(account_id: str, accounts: list[AccountMetadata]) -> str | None:
    account = account_index(accounts).get(account_id)
    if account is None:
        return None
    return account.owner_email


class AccountDirectory:
    def __init__(self, accounts: list[AccountMetadata]) -> None:
        self._accounts = list(accounts)
        self._index = account_index(accounts)

    def get(self, account_id: str) -> AccountMetadata | None:
        return self._index.get(account_id)

    def require(self, account_id: str) -> AccountMetadata:
        account = self.get(account_id)
        if account is None:
            raise KeyError(account_id)
        return account

    def contains(self, account_id: str) -> bool:
        return account_id in self._index

    def business_unit_for(self, account_id: str) -> str:
        account = self.get(account_id)
        if account is None:
            return UNKNOWN_BUSINESS_UNIT
        return account.business_unit

    def activated_tags_for(self, account_id: str) -> tuple[str, ...]:
        account = self.get(account_id)
        if account is None:
            return ()
        return account.activated_tag_keys

    def active_account_ids(self) -> tuple[str, ...]:
        return tuple(account.linked_account_id for account in active_accounts(self._accounts))

    def business_unit_map(self) -> dict[str, list[str]]:
        return accounts_by_business_unit(self._accounts)

