from __future__ import annotations

from cost_models import AccountMetadata, UsageRow


def unknown_account_warning(row: UsageRow) -> dict[str, object]:
    return {
        "linked_account_id": row.linked_account_id,
        "warning": "unknown_account",
        "tags": dict(row.tags),
        "service": row.service,
        "region": row.region,
    }


def inactive_tag_warning(row: UsageRow, tag_key: str) -> dict[str, object]:
    return {
        "linked_account_id": row.linked_account_id,
        "warning": "inactive_tag_ignored",
        "tag_key": tag_key,
        "tag_value": row.tags[tag_key],
        "service": row.service,
        "region": row.region,
    }


def shared_tag_warning(tag_key: str, tag_value: str, account_ids: list[str]) -> dict[str, object]:
    return {
        "warning": "shared_tag_value_observed",
        "tag_key": tag_key,
        "tag_value": tag_value,
        "linked_account_ids": sorted(account_ids),
    }


def inactive_tag_warnings(row: UsageRow, account: AccountMetadata) -> list[dict[str, object]]:
    active = set(account.activated_tag_keys)
    warnings: list[dict[str, object]] = []
    for key in row.tags:
        if key not in active:
            warnings.append(inactive_tag_warning(row, key))
    return warnings


def shared_tag_value_warnings(rows: list[UsageRow]) -> list[dict[str, object]]:
    by_tag: dict[tuple[str, str], set[str]] = {}
    for row in rows:
        for key, value in row.tags.items():
            by_tag.setdefault((key, value), set()).add(row.linked_account_id)
    warnings: list[dict[str, object]] = []
    for (key, value), account_ids in by_tag.items():
        if len(account_ids) <= 1:
            continue
        warnings.append(shared_tag_warning(key, value, sorted(account_ids)))
    warnings.sort(key=lambda warning: (str(warning["tag_key"]), str(warning["tag_value"])))
    return warnings


def dedupe_warnings(warnings: list[dict[str, object]]) -> list[dict[str, object]]:
    seen: set[tuple[tuple[str, str], ...]] = set()
    unique: list[dict[str, object]] = []
    for warning in warnings:
        key = tuple(sorted((str(k), str(v)) for k, v in warning.items()))
        if key in seen:
            continue
        seen.add(key)
        unique.append(warning)
    return unique


class WarningCollector:
    def __init__(self) -> None:
        self._warnings: list[dict[str, object]] = []

    def add(self, warning: dict[str, object]) -> None:
        self._warnings.append(warning)

    def extend(self, warnings: list[dict[str, object]]) -> None:
        self._warnings.extend(warnings)

    def all(self) -> list[dict[str, object]]:
        return list(self._warnings)

    def unique(self) -> list[dict[str, object]]:
        return dedupe_warnings(self._warnings)

    def count(self) -> int:
        return len(self._warnings)

