from __future__ import annotations

from account_directory import AccountDirectory
from audit_warnings import WarningCollector, inactive_tag_warnings, shared_tag_value_warnings, unknown_account_warning
from cost_models import AccountMetadata, CostMonitor, UsageRow
from monitor_config import MonitorRunner, monitor_scope_summary
from report_builder import root_cause_dict, summarize_anomaly_report as build_report
from tag_attribution import business_unit_for_row, tag_context_cache, tag_health_snapshot
from usage_aggregation import UsageAggregator, root_cause_key


def _account_index(accounts: list[AccountMetadata]) -> dict[str, AccountMetadata]:
    return {account.linked_account_id: account for account in accounts}


def _tag_context_cache(rows: list[UsageRow], accounts: list[AccountMetadata]) -> dict[str, str]:
    return tag_context_cache(rows, accounts)


def _root_cause_key(row: UsageRow) -> tuple[str, str, str]:
    return root_cause_key(row)


def _valid_rows(rows: list[UsageRow], directory: AccountDirectory, warnings: WarningCollector) -> list[UsageRow]:
    valid: list[UsageRow] = []
    for row in rows:
        account = directory.get(row.linked_account_id)
        if account is None:
            warnings.add(unknown_account_warning(row))
            continue
        warnings.extend(inactive_tag_warnings(row, account))
        valid.append(row)
    return valid


def _business_unit_totals(
    rows: list[UsageRow],
    accounts: list[AccountMetadata],
    warnings: WarningCollector,
) -> dict[str, int]:
    directory = AccountDirectory(accounts)
    cache = _tag_context_cache(rows, accounts)
    totals: dict[str, int] = {}
    for row in rows:
        account = directory.get(row.linked_account_id)
        if account is None:
            continue
        business_unit = business_unit_for_row(row, account, cache)
        totals[business_unit] = totals.get(business_unit, 0) + row.cost_cents
    warnings.extend(shared_tag_value_warnings(rows))
    return totals


def _root_causes(rows: list[UsageRow], accounts: list[AccountMetadata]) -> list[dict[str, object]]:
    directory = AccountDirectory(accounts)
    root_totals: dict[tuple[str, str, str], int] = {}
    for row in rows:
        key = _root_cause_key(row)
        root_totals[key] = root_totals.get(key, 0) + row.cost_cents

    causes: list[dict[str, object]] = []
    for (linked_account_id, service, region), cost_cents in root_totals.items():
        account = directory.require(linked_account_id)
        causes.append(
            root_cause_dict(
                linked_account_id=linked_account_id,
                account_name=account.account_name,
                business_unit=account.business_unit,
                service=service,
                region=region,
                cost_cents=cost_cents,
            )
        )
    return causes


def explain_cost_anomalies(
    rows: list[UsageRow],
    accounts: list[AccountMetadata],
    monitor: CostMonitor | None = None,
) -> dict[str, object]:
    directory = AccountDirectory(accounts)
    runner = MonitorRunner(monitor)
    scoped_rows = runner.filter(rows)
    warnings = WarningCollector()
    valid_rows = _valid_rows(scoped_rows, directory, warnings)
    aggregator = UsageAggregator(valid_rows)

    root_causes = _root_causes(valid_rows, accounts)
    account_totals = aggregator.account_totals()
    business_unit_totals = _business_unit_totals(valid_rows, accounts, warnings)

    report = build_report(
        root_causes,
        account_totals,
        business_unit_totals,
        warnings.all(),
        service_totals=aggregator.service_totals(),
        region_totals=aggregator.region_totals(),
        monitor_scope=monitor_scope_summary(monitor),
    )
    report["tag_health"] = tag_health_snapshot(scoped_rows, accounts)
    return report


def summarize_anomaly_report(
    root_causes: list[dict[str, object]],
    account_totals: dict[str, int],
    business_unit_totals: dict[str, int],
    audit_warnings: list[dict[str, object]],
) -> dict[str, object]:
    return build_report(root_causes, account_totals, business_unit_totals, audit_warnings)


class OrganizationsCostExplainer:
    def __init__(self, accounts: list[AccountMetadata], monitor: CostMonitor | None = None) -> None:
        self.accounts = list(accounts)
        self.monitor = monitor

    def explain(self, rows: list[UsageRow]) -> dict[str, object]:
        return explain_cost_anomalies(rows, self.accounts, self.monitor)

    def account_count(self) -> int:
        return len(self.accounts)

    def tag_health(self, rows: list[UsageRow]) -> dict[str, object]:
        return tag_health_snapshot(rows, self.accounts)

