from __future__ import annotations

from dataclasses import dataclass


VALID_MONITOR_TYPES = {"ACCOUNT", "SERVICE", "TAG", "COST_CATEGORY"}
VALID_SEVERITIES = {"low", "medium", "high", "critical"}


def _require_text(value: str, field_name: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class UsageRow:
    linked_account_id: str
    service: str
    region: str
    usage_type: str
    cost_cents: int
    tags: dict[str, str]
    billing_period: str = "2026-05"
    currency: str = "USD"

    def __post_init__(self) -> None:
        _require_text(self.linked_account_id, "linked_account_id")
        _require_text(self.service, "service")
        _require_text(self.region, "region")
        _require_text(self.usage_type, "usage_type")
        if self.cost_cents < 0:
            raise ValueError("cost_cents must be non-negative")
        _require_text(self.billing_period, "billing_period")
        _require_text(self.currency, "currency")
        for key, value in self.tags.items():
            _require_text(key, "tag key")
            _require_text(value, "tag value")


@dataclass(frozen=True)
class AccountMetadata:
    linked_account_id: str
    account_name: str
    business_unit: str
    activated_tag_keys: tuple[str, ...]
    payer_account_id: str = "000000000000"
    owner_email: str = "finance@example.com"
    account_status: str = "ACTIVE"
    cost_category: str | None = None

    def __post_init__(self) -> None:
        _require_text(self.linked_account_id, "linked_account_id")
        _require_text(self.account_name, "account_name")
        _require_text(self.business_unit, "business_unit")
        _require_text(self.payer_account_id, "payer_account_id")
        _require_text(self.owner_email, "owner_email")
        _require_text(self.account_status, "account_status")
        for key in self.activated_tag_keys:
            _require_text(key, "activated_tag_key")
        if self.cost_category is not None:
            _require_text(self.cost_category, "cost_category")


@dataclass(frozen=True)
class CostMonitor:
    monitor_id: str
    monitor_type: str
    name: str
    linked_account_ids: tuple[str, ...]
    services: tuple[str, ...] = ()
    tag_key: str | None = None
    min_cost_cents: int = 0

    def __post_init__(self) -> None:
        _require_text(self.monitor_id, "monitor_id")
        _require_text(self.monitor_type, "monitor_type")
        _require_text(self.name, "name")
        if self.monitor_type not in VALID_MONITOR_TYPES:
            raise ValueError("unsupported monitor_type")
        if self.min_cost_cents < 0:
            raise ValueError("min_cost_cents must be non-negative")
        for account_id in self.linked_account_ids:
            _require_text(account_id, "linked_account_id")
        for service in self.services:
            _require_text(service, "service")
        if self.tag_key is not None:
            _require_text(self.tag_key, "tag_key")


@dataclass(frozen=True)
class RootCauseKey:
    linked_account_id: str
    service: str
    region: str
    usage_type: str | None = None

    def __post_init__(self) -> None:
        _require_text(self.linked_account_id, "linked_account_id")
        _require_text(self.service, "service")
        _require_text(self.region, "region")
        if self.usage_type is not None:
            _require_text(self.usage_type, "usage_type")


@dataclass(frozen=True)
class AttributionResult:
    linked_account_id: str
    account_name: str
    business_unit: str
    service: str
    region: str
    cost_cents: int
    tag_context: dict[str, str]
    audit_warnings: tuple[dict[str, object], ...] = ()

    def __post_init__(self) -> None:
