from __future__ import annotations

from cost_models import CostMonitor, UsageRow


def row_matches_monitor(row: UsageRow, monitor: CostMonitor) -> bool:
    if monitor.linked_account_ids and row.linked_account_id not in monitor.linked_account_ids:
        return False
    if monitor.services and row.service not in monitor.services:
        return False
    if monitor.tag_key is not None and monitor.tag_key not in row.tags:
        return False
    if row.cost_cents < monitor.min_cost_cents:
        return False
    return True


def filter_rows_for_monitor(rows: list[UsageRow], monitor: CostMonitor | None) -> list[UsageRow]:
    if monitor is None:
        return list(rows)
    return [row for row in rows if row_matches_monitor(row, monitor)]


def monitor_scope_summary(monitor: CostMonitor | None) -> dict[str, object]:
    if monitor is None:
        return {
            "monitor_id": None,
            "monitor_type": "ALL",
            "linked_account_ids": [],
            "services": [],
            "tag_key": None,
            "min_cost_cents": 0,
        }
    return {
        "monitor_id": monitor.monitor_id,
        "monitor_type": monitor.monitor_type,
        "linked_account_ids": list(monitor.linked_account_ids),
        "services": list(monitor.services),
        "tag_key": monitor.tag_key,
        "min_cost_cents": monitor.min_cost_cents,
    }


def monitor_covered_accounts(monitor: CostMonitor | None, rows: list[UsageRow]) -> tuple[str, ...]:
    if monitor is None:
        return tuple(sorted({row.linked_account_id for row in rows}))
    if monitor.linked_account_ids:
        return tuple(sorted(monitor.linked_account_ids))
    return tuple(sorted({row.linked_account_id for row in rows if row_matches_monitor(row, monitor)}))


class MonitorRunner:
    def __init__(self, monitor: CostMonitor | None = None) -> None:
        self.monitor = monitor

    def filter(self, rows: list[UsageRow]) -> list[UsageRow]:
        return filter_rows_for_monitor(rows, self.monitor)

    def scope(self) -> dict[str, object]:
        return monitor_scope_summary(self.monitor)

    def covered_accounts(self, rows: list[UsageRow]) -> tuple[str, ...]:
        return monitor_covered_accounts(self.monitor, rows)

