from __future__ import annotations

from account_directory import AccountDirectory
from audit_warnings import inactive_tag_warnings, shared_tag_value_warnings
from cost_models import AccountMetadata, UsageRow


def activated_tag_values(row: UsageRow, account: AccountMetadata) -> dict[str, str]:
    active_keys = set(account.activated_tag_keys)
    return {
        key: value
        for key, value in row.tags.items()
        if key in active_keys
    }


def inactive_tag_values(row: UsageRow, account: AccountMetadata) -> dict[str, str]:
    active_keys = set(account.activated_tag_keys)
    return {
        key: value
        for key, value in row.tags.items()
        if key not in active_keys
    }


def tag_context_cache(rows: list[UsageRow], accounts: list[AccountMetadata]) -> dict[str, str]:
    directory = AccountDirectory(accounts)
    cache: dict[str, str] = {}
    for row in rows:
        account = directory.get(row.linked_account_id)
        if account is None:
            continue
        for value in activated_tag_values(row, account).values():
            cache[value] = account.business_unit
    return cache


def account_scoped_tag_context(rows: list[UsageRow], accounts: list[AccountMetadata]) -> dict[tuple[str, str, str], str]:
    directory = AccountDirectory(accounts)
    scoped: dict[tuple[str, str, str], str] = {}
    for row in rows:
        account = directory.get(row.linked_account_id)
        if account is None:
            continue
        for key, value in activated_tag_values(row, account).items():
            scoped[(row.linked_account_id, key, value)] = account.business_unit
    return scoped


def business_unit_for_row(row: UsageRow, account: AccountMetadata, cache: dict[str, str]) -> str:
    active_values = list(activated_tag_values(row, account).values())
    if not active_values:
        return account.business_unit
    return cache[active_values[0]]


def scoped_business_unit_for_row(
    row: UsageRow,
    account: AccountMetadata,
    scoped_cache: dict[tuple[str, str, str], str],
) -> str:
    for key, value in activated_tag_values(row, account).items():
        business_unit = scoped_cache.get((row.linked_account_id, key, value))
        if business_unit is not None:
            return business_unit
    return account.business_unit


def attribution_detail(row: UsageRow, account: AccountMetadata, cache: dict[str, str]) -> dict[str, object]:
    active = activated_tag_values(row, account)
    inactive = inactive_tag_values(row, account)
    return {
        "linked_account_id": row.linked_account_id,
        "account_name": account.account_name,
        "business_unit": business_unit_for_row(row, account, cache),
        "account_business_unit": account.business_unit,
        "service": row.service,
        "region": row.region,
        "usage_type": row.usage_type,
        "cost_cents": row.cost_cents,
        "activated_tags": active,
        "inactive_tags": inactive,
        "audit_warnings": inactive_tag_warnings(row, account),
    }


def tag_value_accounts(rows: list[UsageRow]) -> dict[tuple[str, str], list[str]]:
    grouped: dict[tuple[str, str], set[str]] = {}
    for row in rows:
        for key, value in row.tags.items():
            grouped.setdefault((key, value), set()).add(row.linked_account_id)
    return {
        tag: sorted(account_ids)
        for tag, account_ids in grouped.items()
    }


def tag_health_snapshot(rows: list[UsageRow], accounts: list[AccountMetadata]) -> dict[str, object]:
    directory = AccountDirectory(accounts)
    unknown_rows = [row for row in rows if not directory.contains(row.linked_account_id)]
    inactive_count = 0
    active_count = 0
    for row in rows:
        account = directory.get(row.linked_account_id)
        if account is None:
            continue
        active_count += len(activated_tag_values(row, account))
        inactive_count += len(inactive_tag_values(row, account))
    return {
        "row_count": len(rows),
        "unknown_account_row_count": len(unknown_rows),
        "active_tag_count": active_count,
        "inactive_tag_count": inactive_count,
        "shared_tag_warning_count": len(shared_tag_value_warnings(rows)),
    }


class TagAttributor:
    def __init__(self, accounts: list[AccountMetadata]) -> None:
        self.accounts = list(accounts)

    def cache(self, rows: list[UsageRow]) -> dict[str, str]:
        return tag_context_cache(rows, self.accounts)

    def scoped_cache(self, rows: list[UsageRow]) -> dict[tuple[str, str, str], str]:
        return account_scoped_tag_context(rows, self.accounts)

    def business_unit(self, row: UsageRow, account: AccountMetadata, rows: list[UsageRow]) -> str:
        return business_unit_for_row(row, account, self.cache(rows))

    def detail(self, row: UsageRow, account: AccountMetadata, rows: list[UsageRow]) -> dict[str, object]:
        return attribution_detail(row, account, self.cache(rows))

    def health(self, rows: list[UsageRow]) -> dict[str, object]:
        return tag_health_snapshot(rows, self.accounts)

