from __future__ import annotations

from cost_models import RootCauseKey, UsageRow


def root_cause_key(row: UsageRow) -> tuple[str, str, str]:
    return (row.linked_account_id, row.service, row.region)


def detailed_root_cause_key(row: UsageRow) -> RootCauseKey:
    return RootCauseKey(
        linked_account_id=row.linked_account_id,
        service=row.service,
        region=row.region,
        usage_type=row.usage_type,
    )


def add_cost(total: dict[str, int], key: str, cost_cents: int) -> None:
    total[key] = total.get(key, 0) + cost_cents


def account_totals(rows: list[UsageRow]) -> dict[str, int]:
    totals: dict[str, int] = {}
    for row in rows:
        add_cost(totals, row.linked_account_id, row.cost_cents)
    return totals


def service_totals(rows: list[UsageRow]) -> dict[str, int]:
    totals: dict[str, int] = {}
    for row in rows:
        add_cost(totals, row.service, row.cost_cents)
    return totals


def region_totals(rows: list[UsageRow]) -> dict[str, int]:
    totals: dict[str, int] = {}
    for row in rows:
        add_cost(totals, row.region, row.cost_cents)
    return totals


def root_totals(rows: list[UsageRow]) -> dict[tuple[str, str, str], int]:
    totals: dict[tuple[str, str, str], int] = {}
    for row in rows:
        key = root_cause_key(row)
        totals[key] = totals.get(key, 0) + row.cost_cents
    return totals


def sort_root_causes(root_causes: list[dict[str, object]]) -> list[dict[str, object]]:
    return sorted(
        root_causes,
        key=lambda item: (
            -int(item["cost_cents"]),
            str(item["linked_account_id"]),
            str(item.get("service", "")),
            str(item.get("region", "")),
        ),
    )


def total_cost(rows: list[UsageRow]) -> int:
    return sum(row.cost_cents for row in rows)


class UsageAggregator:
    def __init__(self, rows: list[UsageRow]) -> None:
        self.rows = list(rows)

    def account_totals(self) -> dict[str, int]:
        return account_totals(self.rows)

    def service_totals(self) -> dict[str, int]:
        return service_totals(self.rows)

    def region_totals(self) -> dict[str, int]:
        return region_totals(self.rows)

    def root_totals(self) -> dict[tuple[str, str, str], int]:
        return root_totals(self.rows)

    def total_cost(self) -> int:
        return total_cost(self.rows)

    def rows_for_account(self, account_id: str) -> list[UsageRow]:
        return [row for row in self.rows if row.linked_account_id == account_id]

    def rows_for_service(self, service: str) -> list[UsageRow]:
        return [row for row in self.rows if row.service == service]

