import pytest

from account_directory import AccountDirectory
from audit_warnings import shared_tag_value_warnings
from cost_explainer import OrganizationsCostExplainer, explain_cost_anomalies, summarize_anomaly_report
from cost_models import AnomalyWindow, CostMonitor, UsageRow, account, monitor
from monitor_config import MonitorRunner
from report_builder import top_root_causes
from tag_attribution import account_scoped_tag_context, tag_health_snapshot
from usage_aggregation import UsageAggregator


def usage(
    linked_account_id: str,
    cost_cents: int,
    service: str = "AmazonCloudFront",
    region: str = "global",
    usage_type: str = "DataTransfer-Out-Bytes",
    tags: dict[str, str] | None = None,
) -> UsageRow:
    return UsageRow(
        linked_account_id=linked_account_id,
        service=service,
        region=region,
        usage_type=usage_type,
        cost_cents=cost_cents,
        tags=tags or {},
    )


def accounts():
    return [
        account("111111111111", "legacy-news-prod", "News", ["CostCenter"]),
        account("222222222222", "streaming-launch-prod", "Streaming", ["CostCenter"]),
        account("333333333333", "shared-platform", "Platform", []),
    ]


def launch_monitor() -> CostMonitor:
    return monitor(
        "mon-launch",
        "Streaming launch monitor",
        ["222222222222"],
        services=["AmazonCloudFront"],
        tag_key="CostCenter",
    )


def test_happy_path_single_account_anomaly_uses_account_business_unit():
    report = explain_cost_anomalies(
        [usage("222222222222", 12_500, tags={"CostCenter": "Launch"})],
        accounts(),
    )

    assert report["total_cost_cents"] == 12_500
    assert report["account_totals"] == {"222222222222": 12_500}
    assert report["business_unit_totals"] == {"Streaming": 12_500}
    assert report["root_causes"][0]["account_name"] == "streaming-launch-prod"
    assert report["service_totals"] == {"AmazonCloudFront": 12_500}


def test_shared_tag_value_does_not_leak_business_unit_between_accounts():
    report = explain_cost_anomalies(
        [
            usage("111111111111", 4_000, tags={"CostCenter": "Launch"}),
            usage("222222222222", 9_000, tags={"CostCenter": "Launch"}),
        ],
        accounts(),
    )

    assert report["account_totals"] == {
        "111111111111": 4_000,
        "222222222222": 9_000,
    }
    assert report["business_unit_totals"] == {
        "News": 4_000,
        "Streaming": 9_000,
    }
    assert [item["linked_account_id"] for item in report["root_causes"]] == ["222222222222", "111111111111"]


def test_inactive_tag_is_ignored_for_business_unit_but_audited():
    report = explain_cost_anomalies(
        [usage("333333333333", 3_500, service="AmazonEC2", region="us-east-1", tags={"CostCenter": "Launch"})],
        accounts(),
    )

    assert report["business_unit_totals"] == {"Platform": 3_500}
    assert report["audit_warning_count"] == 1
    assert report["audit_warnings"][0]["warning"] == "inactive_tag_ignored"
    assert report["audit_warnings"][0]["tag_value"] == "Launch"


def test_root_causes_aggregate_by_account_service_and_region():
    report = explain_cost_anomalies(
        [
            usage("222222222222", 4_000, service="AmazonCloudFront", region="global"),
            usage("222222222222", 1_500, service="AmazonCloudFront", region="global"),
            usage("222222222222", 2_000, service="AmazonS3", region="us-east-1"),
        ],
        accounts(),
    )

    assert report["root_causes"][0]["service"] == "AmazonCloudFront"
    assert report["root_causes"][0]["cost_cents"] == 5_500
    assert report["root_causes"][1]["service"] == "AmazonS3"
    assert report["root_causes"][1]["cost_cents"] == 2_000


def test_unknown_account_is_audited_and_not_counted():
    report = explain_cost_anomalies(
        [usage("999999999999", 9_999, tags={"CostCenter": "Mystery"})],
        accounts(),
    )

    assert report["total_cost_cents"] == 0
    assert report["root_causes"] == []
    assert report["audit_warnings"][0]["warning"] == "unknown_account"


def test_class_workflow_preserves_public_entrypoint():
    explainer = OrganizationsCostExplainer(accounts())

    report = explainer.explain([usage("111111111111", 2_000), usage("222222222222", 5_000)])

    assert report["total_cost_cents"] == 7_000
    assert report["business_unit_totals"] == {"News": 2_000, "Streaming": 5_000}


def test_monitor_filters_rows_to_configured_account_service_and_tag_key():
    report = explain_cost_anomalies(
        [
            usage("111111111111", 4_000, tags={"CostCenter": "Launch"}),
            usage("222222222222", 9_000, tags={"CostCenter": "Launch"}),
            usage("222222222222", 7_000, service="AmazonS3", region="us-east-1", tags={"CostCenter": "Launch"}),
            usage("222222222222", 1_000, service="AmazonCloudFront", tags={"Team": "Growth"}),
        ],
        accounts(),
        launch_monitor(),
    )

    assert report["total_cost_cents"] == 9_000
    assert report["account_totals"] == {"222222222222": 9_000}
    assert report["monitor_scope"]["monitor_id"] == "mon-launch"


def test_account_directory_groups_accounts_by_business_unit():
    directory = AccountDirectory(accounts())

    assert directory.business_unit_map() == {
        "News": ["111111111111"],
        "Streaming": ["222222222222"],
        "Platform": ["333333333333"],
    }
    assert directory.active_account_ids() == ("111111111111", "222222222222", "333333333333")


def test_shared_tag_warning_keeps_account_boundary_visible():
    warnings = shared_tag_value_warnings(
        [
            usage("111111111111", 4_000, tags={"CostCenter": "Launch"}),
            usage("222222222222", 9_000, tags={"CostCenter": "Launch"}),
        ]
    )

    assert warnings == [
        {
            "warning": "shared_tag_value_observed",
            "tag_key": "CostCenter",
            "tag_value": "Launch",
            "linked_account_ids": ["111111111111", "222222222222"],
        }
    ]


def test_account_scoped_tag_context_tracks_same_value_per_account():
    scoped = account_scoped_tag_context(
        [
            usage("111111111111", 4_000, tags={"CostCenter": "Launch"}),
            usage("222222222222", 9_000, tags={"CostCenter": "Launch"}),
        ],
        accounts(),
    )

    assert scoped[("111111111111", "CostCenter", "Launch")] == "News"
    assert scoped[("222222222222", "CostCenter", "Launch")] == "Streaming"


def test_tag_health_counts_active_inactive_shared_and_unknown_rows():
    health = tag_health_snapshot(
        [
            usage("111111111111", 4_000, tags={"CostCenter": "Launch", "Owner": "news"}),
            usage("222222222222", 9_000, tags={"CostCenter": "Launch"}),
            usage("999999999999", 1_000, tags={"CostCenter": "Mystery"}),
        ],
        accounts(),
    )

    assert health["row_count"] == 3
    assert health["unknown_account_row_count"] == 1
    assert health["active_tag_count"] == 2
    assert health["inactive_tag_count"] == 1
    assert health["shared_tag_warning_count"] == 1


def test_root_causes_sort_stably_when_costs_tie():
    report = explain_cost_anomalies(
        [
            usage("222222222222", 5_000, service="AmazonS3", region="us-east-1"),
            usage("111111111111", 5_000, service="AmazonCloudFront", region="global"),
        ],
        accounts(),
    )

    assert [root["linked_account_id"] for root in report["root_causes"]] == ["111111111111", "222222222222"]


def test_business_unit_totals_fallback_to_account_when_no_tags_exist():
    report = explain_cost_anomalies(
        [
            usage("111111111111", 2_000, tags={}),
            usage("222222222222", 3_000, tags={}),
            usage("333333333333", 4_000, tags={}),
        ],
        accounts(),
    )

    assert report["business_unit_totals"] == {
        "News": 2_000,
        "Streaming": 3_000,
        "Platform": 4_000,
    }


def test_region_and_service_totals_are_included_for_incident_review():
    report = explain_cost_anomalies(
        [
            usage("222222222222", 4_000, service="AmazonCloudFront", region="global"),
            usage("222222222222", 2_000, service="AmazonS3", region="us-east-1"),
            usage("222222222222", 1_500, service="AmazonS3", region="us-east-1"),
        ],
        accounts(),
    )

    assert report["service_totals"] == {"AmazonCloudFront": 4_000, "AmazonS3": 3_500}
    assert report["region_totals"] == {"global": 4_000, "us-east-1": 3_500}


def test_monitor_runner_reports_covered_accounts():
    runner = MonitorRunner(launch_monitor())

    covered = runner.covered_accounts(
        [
            usage("111111111111", 4_000, tags={"CostCenter": "Launch"}),
            usage("222222222222", 9_000, tags={"CostCenter": "Launch"}),
        ]
    )

    assert covered == ("222222222222",)


def test_usage_aggregator_keeps_account_service_region_totals_separate():
    aggregator = UsageAggregator(
        [
            usage("111111111111", 4_000, service="AmazonCloudFront", region="global"),
            usage("111111111111", 1_000, service="AmazonCloudFront", region="global"),
            usage("222222222222", 9_000, service="AmazonCloudFront", region="global"),
        ]
    )

    assert aggregator.account_totals() == {"111111111111": 5_000, "222222222222": 9_000}
    assert aggregator.root_totals()[("111111111111", "AmazonCloudFront", "global")] == 5_000
    assert aggregator.total_cost() == 14_000


def test_summarize_anomaly_report_preserves_public_shape():
    summary = summarize_anomaly_report(
        [{"linked_account_id": "111111111111", "cost_cents": 10_000}],
        {"111111111111": 10_000},
        {"News": 10_000},
        [{"warning": "inactive_tag_ignored"}],
    )

    assert summary["total_cost_cents"] == 10_000
    assert summary["audit_warning_count"] == 1
    assert summary["business_unit_totals"] == {"News": 10_000}


def test_top_root_causes_returns_requested_limit():
    report = explain_cost_anomalies(
        [
            usage("111111111111", 4_000, service="AmazonCloudFront"),
            usage("222222222222", 9_000, service="AmazonS3", region="us-east-1"),
            usage("333333333333", 2_000, service="AmazonEC2", region="us-east-1"),
        ],
        accounts(),
    )

    assert [item["cost_cents"] for item in top_root_causes(report, 2)] == [9_000, 4_000]


def test_monitor_can_filter_by_minimum_cost():
    high_cost_monitor = monitor(
        "mon-expensive",
        "High cost rows",
        ["222222222222"],
        min_cost_cents=5_000,
    )

    report = explain_cost_anomalies(
        [
            usage("222222222222", 4_999, service="AmazonCloudFront"),
            usage("222222222222", 5_000, service="AmazonCloudFront"),
        ],
        accounts(),
        high_cost_monitor,
    )

    assert report["total_cost_cents"] == 5_000


def test_duplicate_inactive_tag_rows_produce_one_warning_per_row():
    report = explain_cost_anomalies(
        [
            usage("333333333333", 1_000, tags={"CostCenter": "Launch"}),
            usage("333333333333", 2_000, tags={"CostCenter": "Launch"}),
        ],
        accounts(),
    )

    assert report["audit_warning_count"] == 2
    assert [warning["tag_value"] for warning in report["audit_warnings"]] == ["Launch", "Launch"]


def test_same_tag_value_three_accounts_does_not_collapse_business_units():
    extended_accounts = accounts() + [account("444444444444", "sports-prod", "Sports", ["CostCenter"])]

    report = explain_cost_anomalies(
        [
            usage("111111111111", 1_000, tags={"CostCenter": "Launch"}),
            usage("222222222222", 2_000, tags={"CostCenter": "Launch"}),
            usage("444444444444", 3_000, tags={"CostCenter": "Launch"}),
        ],
        extended_accounts,
    )

    assert report["business_unit_totals"] == {
        "News": 1_000,
        "Streaming": 2_000,
        "Sports": 3_000,
    }


def test_cost_monitor_rejects_negative_minimum_cost():
    with pytest.raises(ValueError):
        monitor("bad", "Bad monitor", [], min_cost_cents=-1)


def test_anomaly_window_rejects_invalid_range():
    with pytest.raises(ValueError):
        AnomalyWindow(billing_period="2026-05", start_day=5, end_day=4, severity="high")


def test_account_metadata_rejects_blank_activated_tag_key():
    with pytest.raises(ValueError):
        account("555555555555", "bad-account", "Bad", [""])


def test_unexpected_negative_cost_is_rejected():
    with pytest.raises(ValueError):
        usage("111111111111", -1)
